const r = $input.first().json;
const TICKET = Number($env.TICKET_MEDIO || 180);                       // estimativa, ajustar com o financeiro
const pct = (a, b) => b ? Math.round(1000 * a / b) / 10 : 0;
const kpi = {
  reversao_faltas_pct: pct(r.remarcadas, r.faltas_total),              // remarcados ÷ (no-show + cancelados + remarcados)
  reversao_vagas_pct: pct(r.encaixes, r.vagas_liberadas),              // encaixe_confirmado ÷ vaga_liberada
  receita_recuperada_estimada: (Number(r.remarcadas) + Number(r.encaixes)) * TICKET,
  tempo_cobertura_min: Math.round(r.tempo_cobertura_min * 10) / 10,
  gerado_em: new Date().toISOString(), correlation_id: 'KPI-' + Date.now().toString(36)
};
kpi.abaixo_da_meta = kpi.reversao_faltas_pct < 40 || kpi.reversao_vagas_pct < 50;   // metas sugeridas
return [{ json: kpi }];
